import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import sorsuLogo from "../assets/sorsu-logo.png";

const API_URL = "http://localhost:5000";

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [selected, setSelected] = useState({});
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [hasVoted, setHasVoted] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");

  const [showFeedback, setShowFeedback] = useState(false);
  const [feedbackText, setFeedbackText] = useState("");
  const [rating, setRating] = useState(0);

  const navigate = useNavigate();

  // ======================
  // FETCH DATA
  // ======================
  useEffect(() => {
    const fetchData = async () => {
      try {
        const resCandidates = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(resCandidates.data);

        if (auth?.token) {
          const resVotes = await axios.get(`${API_URL}/api/votes/my`, {
            headers: { Authorization: `Bearer ${auth.token}` },
          });

          const selectedVotes = {};
          resVotes.data.forEach((v) => {
            if (v.position && v.candidateId) {
              selectedVotes[v.position] = v.candidateId;
            }
          });

          setSelected(selectedVotes);
          if (resVotes.data.length > 0) setHasVoted(true);
        }
      } catch (err) {
        console.error(err);
        setModalType("error");
        setModalMessage("Failed to load data.");
        setShowModal(true);
      }
      setLoading(false);
    };

    fetchData();
  }, [auth]);

  // ======================
  // GROUP BY POSITION
  // ======================
  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, c) => {
      const pos = c.candidacy;
      if (!groups[pos]) groups[pos] = [];
      groups[pos].push(c);
      return groups;
    }, {});
  }, [candidates]);

  // ======================
  // SELECT
  // ======================
  const handleSelect = (position, id) => {
    if (hasVoted) return;

    setSelected((prev) => ({
      ...prev,
      [position]: prev[position] === id ? null : id,
    }));
  };

  // ======================
  // CAST BUTTON
  // ======================
  const handleCastVote = () => {
    if (!auth?.token) {
      setModalType("error");
      setModalMessage("Login required.");
      setShowModal(true);
      return;
    }

    if (Object.values(selected).filter(Boolean).length === 0) {
      setModalType("error");
      setModalMessage("Select at least one candidate.");
      setShowModal(true);
      return;
    }

    setModalType("confirm");
    setModalMessage("Are you sure you want to vote?");
    setShowModal(true);
  };

  // ======================
  // CONFIRM VOTE (FIXED 🔥)
  // ======================
  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/votes/batch`, // ✅ FIXED
        {
          candidateIds: Object.values(selected).filter(Boolean),
        },
        {
          headers: {
            Authorization: `Bearer ${auth.token}`,
          },
        }
      );

      setHasVoted(true);
      setSelected({});
      setShowModal(false);
      setShowFeedback(true);
    } catch (err) {
      console.error(err);
      setModalType("error");
      setModalMessage(
        err.response?.data?.message || "Vote failed."
      );
      setShowModal(true);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div style={{ padding: 50 }}>Loading...</div>;

  return (
    <div style={{ padding: 40 }}>
      <h1 style={{ textAlign: "center" }}>
        <img src={sorsuLogo} alt="" style={{ height: 40 }} /> Voting System
      </h1>

      {Object.entries(groupedCandidates).map(([position, list]) => (
        <div key={position}>
          <h2>{position}</h2>

          <div style={{ display: "flex", gap: 20 }}>
            {list.map((c) => {
              const isSelected = selected[position] === c._id;

              return (
                <div
                  key={c._id}
                  onClick={() => handleSelect(position, c._id)}
                  style={{
                    border: isSelected ? "3px solid red" : "1px solid gray",
                    padding: 10,
                    cursor: "pointer",
                  }}
                >
                  <img
                    src={`${API_URL}/uploads/${c.image}`}
                    alt=""
                    width={150}
                  />
                  <h4>{c.firstName} {c.lastName}</h4>
                </div>
              );
            })}
          </div>
        </div>
      ))}

      {!hasVoted && (
        <div style={{ textAlign: "center", marginTop: 30 }}>
          <button onClick={handleCastVote}>
            {submitting ? "Submitting..." : "Cast Vote"}
          </button>
        </div>
      )}

      {/* MODAL */}
      {showModal && (
        <div>
          <h3>{modalMessage}</h3>

          {modalType === "confirm" ? (
            <>
              <button onClick={() => setShowModal(false)}>Cancel</button>
              <button onClick={confirmVote}>Confirm</button>
            </>
          ) : (
            <button onClick={() => setShowModal(false)}>OK</button>
          )}
        </div>
      )}

      {/* FEEDBACK */}
      {showFeedback && (
        <div>
          <h3>Feedback</h3>

          <textarea
            value={feedbackText}
            onChange={(e) => setFeedbackText(e.target.value)}
          />

          <button
            onClick={async () => {
              await axios.post(
                `${API_URL}/api/feedback`,
                { message: feedbackText, rating },
                {
                  headers: {
                    Authorization: `Bearer ${auth.token}`,
                  },
                }
              );
              navigate("/my-votes");
            }}
          >
            Submit
          </button>

          <button onClick={() => navigate("/my-votes")}>
            Skip
          </button>
        </div>
      )}
    </div>
  );
}

export default VotingPage;
